test_purpose:
(1)

with { UE in E-UTRA TN RRC_Idle state }
ensure that {

   when { UE detects the cell re-selection criteria are met for the cell which belongs to the lower
priority inter-RAT NR NTN Cell and UE has a valid GNSS position }

       then { UE reselects the cell which belongs to the lower priority inter-RAT NR NTN Cell }
                     }

(2)

with { UE in E-UTRA TN RRC_Idle state }
ensure that {

   when { UE detects the cell re-selection criteria are met for the cell which belongs to the higher
priority inter-RAT NR NTN Cell and UE has a valid GNSS position }

       then { UE reselects the cell which belongs to the higher priority inter-RAT NR NTN Cell }
                     }
